"""Generate all 15 day HTML files with Customer->Vendor context"""
import json, random
WEEKS = {1: 'week-01', 2: 'week-01', 3: 'week-01', 4: 'week-01', 5: 'week-01', 6: 'week-02', 7: 'week-02', 8: 'week-02', 9: 'week-02', 10: 'week-02', 11: 'week-03', 12: 'week-03', 13: 'week-03', 14: 'week-03', 15: 'week-03'}
CSS = "* { margin: 0; padding: 0; box-sizing: border-box; }\nbody { font-family: -apple-system, system-ui, 'Segoe UI', sans-serif; background: #0d1117; color: #e6edf3; line-height: 1.7; padding: 20px; max-width: 800px; margin: 0 auto; }\nh1 { font-size: 1.5em; color: #58a6ff; }\nh2 { font-size: 1.15em; color: #f0883e; margin: 24px 0 10px; border-bottom: 1px solid #21262d; padding-bottom: 6px; }\nh3 { font-size: 1em; color: #e6edf3; margin: 16px 0 6px; }\np, li { color: #c9d1d9; font-size: 0.95em; }\nul, ol { padding-left: 20px; margin: 6px 0; }\nli { margin: 3px 0; }\n.back { color: #8b949e; text-decoration: none; font-size: 0.85em; display: inline-block; margin-bottom: 12px; }\n.back:hover { color: #58a6ff; }\n.phrase { background: #161b22; border: 1px solid #21262d; border-radius: 8px; padding: 10px 14px; margin: 8px 0; }\n.phrase strong { color: #58a6ff; font-size: 1.02em; }\n.phrase .ru { color: #8b949e; font-size: 0.85em; display: block; margin-top: 3px; }\n.phrase .example { color: #3fb950; font-size: 0.85em; display: block; margin-top: 2px; }\n.dialog { background: #161b22; border-left: 3px solid #58a6ff; border-radius: 0 8px 8px 0; padding: 12px 14px; margin: 10px 0; }\n.dialog .speaker { color: #f0883e; font-weight: 600; }\n.dialog .vendor { color: #d29922; font-weight: 600; }\n.dialog .you { color: #58a6ff; font-weight: 600; }\n.checkbox-item { display: flex; align-items: flex-start; gap: 10px; margin: 8px 0; }\n.checkbox-item input { margin-top: 4px; accent-color: #3fb950; width: 18px; min-width: 18px; height: 18px; }\n.checkbox-item label { font-size: 0.92em; color: #c9d1d9; }\n.prompt-box { background: #0d1117; border: 1px solid #21262d; border-left: 3px solid #d29922; border-radius: 0 8px 8px 0; padding: 10px 14px; margin: 8px 0; font-size: 0.88em; color: #f0c674; white-space: pre-wrap; }\n.tag { display: inline-block; padding: 0 8px; border-radius: 10px; font-size: 0.7em; font-weight: 600; margin: 0 4px 4px 0; }\n.tag-blue { background: #1f6feb33; color: #58a6ff; }\n.tag-green { background: #23863633; color: #3fb950; }\n.tag-orange { background: #d2992233; color: #d29922; }\n.audio-btn { display: inline-flex; align-items: center; gap: 6px; background: #1f6feb; color: #fff; border: none; border-radius: 20px; padding: 6px 14px; font-size: 0.85em; cursor: pointer; margin-top: 8px; }\n.audio-btn:hover { background: #388bfd; }\n.audio-overlay { display: none; position: fixed; inset: 0; background: rgba(0,0,0,0.7); z-index: 999; justify-content: center; align-items: center; }\n.audio-overlay.open { display: flex; }\n.audio-overlay-content { background: #161b22; border: 1px solid #30363d; border-radius: 12px; padding: 24px; max-width: 92%; width: 400px; position: relative; }\n.audio-overlay-content audio { width: 100%; display: block; }\n.audio-close { position: absolute; top: 8px; right: 12px; background: none; border: none; color: #8b949e; font-size: 1.3em; cursor: pointer; line-height: 1; }\n.audio-close:hover { color: #f85149; }\nnav { margin-top: 30px; padding-top: 16px; border-top: 1px solid #21262d; display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px; font-size: 0.85em; }\nnav a { color: #8b949e; text-decoration: none; }\nnav a:hover { color: #58a6ff; }\n@media (max-width: 600px) { body { padding: 12px; } h1 { font-size: 1.25em; } h2 { font-size: 1em; } nav { flex-direction: column; align-items: center; } }"

def gen_day(day, title, focus, date, week_label, review, phrases, words=None, checks=None, reading_title='', **kwargs):
    n = f'{day:02d}'
    week = WEEKS[day]
    cur_week = WEEKS[day]
    if day > 1:
        pw = WEEKS[day - 1]
        prev = f'day-{day - 1:02d}.html' if pw == cur_week else f'../{pw}/day-{day - 1:02d}.html'
    else:
        prev = None
    if day < 15:
        nw = WEEKS[day + 1]
        next_ = f'day-{day + 1:02d}.html' if nw == cur_week else f'../{nw}/day-{day + 1:02d}.html'
    else:
        next_ = None
    nav_prev = f'<a href="{prev}">← {prev}</a>' if prev else '<span style="color:#484f58;">← Day {} (первый)</span>'.format(n)
    nav_next = f'<a href="{next_}">{next_} →</a>' if next_ else '<span style="color:#484f58;">Day {} (последний) →</span>'.format(n)
    ph = ''
    for en, ru in phrases:
        ph += '<div class="phrase"><strong>{en}</strong><span class="ru">{ru}</span></div>\n'.format(en=en, ru=ru)
    ch = ''
    for i, c in enumerate(checks, 1):
        ch += '<div class="checkbox-item"><input type="checkbox" id="sc{i}"><label for="sc{i}">{c}</label></div>\n'.format(i=i, c=c)
    wh = ''
    if words:
        wh = '<table>\n  <tr><th style="color:#f0883e;">English</th><th style="color:#f0883e;">Русский</th></tr>\n'
        for en, ru in words:
            wh += "<tr><td style='color:#58a6ff;'>{en}</td><td style='color:#8b949e;'>{ru}</td></tr>\n".format(en=en, ru=ru)
        wh += '</table>'
    dict_ru = json.dumps([ru for en, ru in phrases], ensure_ascii=False)
    dict_js = '<h2>📝 Самодиктант</h2>\n<p style="font-size:0.88em;color:#8b949e;">Скажи русскую фразу → пауза → скажи по-английски.</p>\n<ol id="dictList-{n}"></ol>\n<script>\n(function() {{\n  var all = {dict_ru};\n  var shuffled = all.sort(function(){{ return Math.random() - 0.5; }}).slice(0, 5);\n  var ol = document.getElementById("dictList-{n}");\n  shuffled.forEach(function(s) {{\n    var li = document.createElement("li");\n    li.textContent = s;\n    ol.appendChild(li);\n  }});\n}})();\n</script>'.format(dict_ru=dict_ru, n=n)
    reading_html = '<h2>📖 Чтение</h2>\n<p><a href="read-{n}.html" style="color:#58a6ff;">Полная страница для чтения →</a></p>'.format(n=n)
    html = '<!DOCTYPE html>\n<html lang="ru">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Day {n} — {title}</title>\n<style>\n{CSS}</style>\n</head>\n<body>\n\n<a class="back" href="../index.html">← На главную</a>\n<h1>Day {n} · {title}</h1>\n<p style="color:#8b949e;font-size:0.9em;">{date} · {week_label} · Новый материал</p>\n\n<div style="background:#1c2128;border-radius:8px;padding:10px 14px;margin:12px 0;font-size:0.88em;">\n  <strong>🎯 Фокус дня:</strong> {focus}<br><button class="audio-btn" onclick="openAudio()">🎵 Аудио дня</button>\n</div>\n\n<h2>🔁 Повторение</h2>\n<p style="color:#8b949e;font-size:0.9em;">{review}</p>\n\n<h2>📘 Новые фразы — {title}</h2>\n\n{ph}\n\n<h2>🎭 AI-практика</h2>\n<p style="font-size:0.88em;color:#8b949e;">Запусти ChatGPT Voice Mode и вставь этот промпт (см. <a href="../common/ai-scenarios.html" style="color:#58a6ff;">AI-сценарии</a>):</p>\n<div class="prompt-box">You are a SAP consultant / vendor representative. I am a customer (process automation manager) with intermediate English. Speak clearly. Topic: {title}. Context: {focus}. Follow my lead in the conversation.</div>\n\n<h2>\U0001f4da \u041d\u043e\u0432\u044b\u0435 \u0441\u043b\u043e\u0432\u0430 \u2014 {title}</h2>\n\n{wh}\n\n{dict_js}\n\n{reading_html}\n\n<h2>✅ Self-check</h2>\n{ch}\n\n<div class="audio-overlay" id="audioOverlay" onclick="closeAudio()">\n  <div class="audio-overlay-content" onclick="event.stopPropagation()">\n    <button class="audio-close" onclick="closeAudio()">✕</button>\n    <audio controls>\n      <source src="../audio/day-{n}.mp3" type="audio/mpeg">\n    </audio>\n  </div>\n</div>\n\n<script>\nfunction openAudio() {{\n  document.getElementById("audioOverlay").classList.add("open");\n  var a = document.querySelector("#audioOverlay audio");\n  if (a) a.play();\n}}\nfunction closeAudio() {{\n  document.getElementById("audioOverlay").classList.remove("open");\n  var a = document.querySelector("#audioOverlay audio");\n  if (a) a.pause();\n}}\n(function() {{\n  var saved = localStorage.getItem("eng-day{n}");\n  if (saved) {{\n    var arr = JSON.parse(saved);\n    document.querySelectorAll(".checkbox-item input").forEach(function(c, i) {{\n      if (arr[i]) c.checked = true;\n    }});\n  }}\n  document.querySelectorAll(".checkbox-item input").forEach(function(c, i) {{\n    c.addEventListener("change", function() {{\n      var all = document.querySelectorAll(".checkbox-item input");\n      var arr = Array.from(all).map(function(x) {{ return x.checked; }});\n      localStorage.setItem("eng-day{n}", JSON.stringify(arr));\n    }});\n  }});\n}})();\n</script>\n\n<nav>\n  {nav_prev}\n  <a href="../index.html">Главная</a>\n  {nav_next}\n</nav>\n\n</body>\n</html>'.format(n=n, title=title, focus=focus, date=date, week_label=week_label, review=review, ph=ph, ch=ch, wh=wh, dict_js=dict_js, reading_html=reading_html, nav_prev=nav_prev, nav_next=nav_next, CSS=CSS)
    path = 'D:\\YD\\General\\4_english\\{week}\\day-{n}.html'.format(week=week, n=n)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(html)
    print('Created: ' + path)
gen_day(1, title='Opening a Meeting with Vendor', focus='Научиться уверенно открывать встречу с SAP-подрядчиком', date='Пн 22 июн 2026', week_label='Week 1 — Заказчик → Подрядчик', review="Первый день — повторения нет. Прочитай вслух цели курса на английском: 'I want to manage vendor meetings in English confidently.' / 'My goal is to clearly explain requirements to SAP consultants.' / 'I will practice every day for 15 days.'", phrases=[('Good morning / afternoon everyone. Thanks for joining the call.', 'Доброе утро/день всем. Спасибо, что подключились к звонку.'), ("Thank you for the proposal you sent. We've reviewed it internally.", 'Спасибо за предложение. Мы его внутренне рассмотрели.'), ("Let's start with the agenda. First topic is a new requirement from the regulator.", 'Давайте начнём с повестки. Первая тема — новое требование от регулятора.'), ('We have participants from both our compliance team and your SAP team today.', 'Сегодня у нас участники от нашего комплаенса и вашей SAP-команды.'), ('Could you briefly introduce your team members?', 'Можете кратко представить участников вашей команды?'), ('The main goal of this meeting is to discuss the new regulatory change.', 'Основная цель встречи — обсудить новое изменение регулятора.'), ("I'll keep the meeting to 45 minutes to respect everyone's time.", 'Я уложу встречу в 45 минут.'), ('Has everyone received the updated requirements document I sent earlier?', 'Все получили обновлённый документ с требованиями?'), ('Feel free to stop me if you have questions at any point.', 'Не стесняйтесь останавливать меня при вопросах.'), ('Let me share my screen to walk through the requirements.', 'Позвольте показать экран и пройтись по требованиям.')], words=[('internally', 'внутренне'), ('compliance', 'комплаенс'), ('regulatory', 'регуляторный'), ('agenda', 'повестка'), ('briefly', 'кратко'), ('regulator', 'регулятор')], checks=['Я могу открыть встречу с подрядчиком и объявить повестку', 'Я могу представить участников со своей стороны', 'Я выучил 10 фраз для открытия встречи с SAP-вендором'], reading_title='Kickoff Meetings with SAP Vendors')
gen_day(2, title='Assigning Tasks to Vendor', focus='Ставить задачи SAP-подрядчику: требования, оценка, сроки', date='Вт 23 июн 2026', week_label='Week 1 — Заказчик → Подрядчик', review='Повторение D01: Открой встречу с подрядчиком вслух: приветствие, 2 темы в agenda.', phrases=[('We have a new business requirement from the regulator.', 'У нас новое требование от регулятора.'), ('Could you assess the impact and give us an estimate?', 'Оцените влияние и дайте оценку?'), ('We need a solution for Chestny Znak. Please prepare a proposal.', 'Нужно решение для Честного Знака. Подготовьте предложение.'), ('What is the timeline for the regulatory deadline?', 'Какие сроки для дедлайна регулятора?'), ('Please provide a cost estimate for this change.', 'Дайте оценку стоимости изменения.'), ('Which SAP modules will be affected?', 'Какие модули SAP затронуты?'), ('Do you need more info from our side to proceed?', 'Нужна доп. информация с нашей стороны?'), ('We need a proposal in two parts: technical + project plan.', 'Нужно предложение из 2 частей: техника + план.'), ('Is this in scope or a change request?', 'Это в scope или change request?'), ('Please confirm receipt and deadline for proposal.', 'Подтвердите получение и срок предложения.')], words=[('assess', 'оценивать'), ('impact', 'влияние'), ('estimate', 'оценка'), ('timeline', 'сроки, график'), ('modules', 'модули'), ('scope', 'объём работ')], checks=['Я могу сформулировать требование и запросить предложение', 'Я могу обсудить сроки и выполнимость', 'Я помню фразы D01 без подсказки'], reading_title='Writing Clear Requirements')
gen_day(3, title='Change Request Due to Regulation', focus='Сообщать подрядчику об изменениях госорганов и инициировать Change Request', date='Ср 24 июн 2026', week_label='Week 1 — Заказчик → Подрядчик', review="Повторение D02: Скажи вслух: 'We have a new requirement...' — объясни требование и запроси оценку.", phrases=[('The regulator updated the requirements. We need to change the scope.', 'Регулятор обновил требования. Нужно изменить scope.'), ('This is a new government requirement. We must implement by [date].', 'Новое требование государства. Внедрить к [дате].'), ('How will this affect the timeline and budget?', 'Как это повлияет на сроки и бюджет?'), ('Please provide a revised proposal with the new scope.', 'Дайте пересмотренное предложение.'), ('We need a formal Change Request to update the contract.', 'Нужен формальный Change Request.'), ('Is this within the current budget or need additional approval?', 'Это в бюджете или нужно согласование?'), ('The regulatory deadline is firm. No extension possible.', 'Дедлайн жёсткий. Продление невозможно.'), ('We need a workaround while the permanent fix is developed.', 'Нужно временное решение.'), ('Can we phase this — MVP by deadline, full solution later?', 'Можно поэтапно: MVP к сроку, потом полное решение?'), ('This change is critical for compliance.', 'Это критично для соблюдения требований.')], words=[('revised', 'пересмотренный'), ('formal', 'формальный'), ('workaround', 'обходное решение'), ('compliance', 'соответствие'), ('budget', 'бюджет'), ('phase', 'этап')], checks=['Я могу инициировать Change Request при изменении регулятора', 'Я могу предложить поэтапное внедрение (MVP + later)', 'Я могу чётко сказать о жёстком дедлайне'], reading_title='Government Regulations and SAP')
gen_day(4, title='Q&A and Clarifying with Vendor', focus='Переспрашивать, уточнять и просить объяснить проще, когда подрядчик говорит сложно или быстро', date='Чт 25 июн 2026', week_label='Week 1 — Заказчик → Подрядчик', review="Повторение D03: Скажи вслух: 'The regulator updated the requirements...' и продолжи.", phrases=[('Sorry, could you repeat that more slowly?', 'Извините, не могли бы вы повторить помедленнее?'), ('Could you explain that in simpler terms?', 'Не могли бы вы объяснить проще?'), ("I didn't quite catch that. Could you say it again?", 'Я не совсем уловил. Повторите, пожалуйста.'), ("What does 'API endpoint' mean in this context?", "Что значит 'API endpoint' в этом контексте?"), ('Could you give me an example?', 'Можете привести пример?'), ('Let me check if I understood correctly: you mean...', 'Давайте проверю, правильно ли я понял: вы имеете в виду...'), ('Could you send a summary of what you just explained?', 'Можете отправить краткое объяснение?'), ('Does this affect the EDI interface or just the API?', 'Это влияет на EDI или только на API?'), ('Are you talking about production or test environment?', 'Вы говорите о промышленной или тестовой среде?'), ('Please confirm I understood the tasks correctly in an email.', 'Подтвердите в письме, что я правильно понял задачи.')], words=[('repeat', 'повторять'), ('simpler', 'проще'), ('context', 'контекст'), ('environment', 'среда'), ('endpoint', 'конечная точка'), ('paraphrase', 'перефразировать')], checks=['Я могу попросить повторить медленнее и проще', "Я могу переспросить, используя 'Let me check if I understood correctly'", 'Я могу попросить пример или письменное объяснение'], reading_title='Clarifying Questions in Vendor Meetings')
gen_day(5, title='Closing Meeting with Vendor', focus='Закрывать встречу: резюмировать, назначать задачи, фиксировать дедлайны', date='Пт 26 июн 2026', week_label='Week 1 — Заказчик → Подрядчик', review="Повторение D04: Представь, что подрядчик сказал сложную фразу. Ответь: 'Sorry, could you repeat that more slowly?'", phrases=[("Let me summarize what we've agreed on today.", 'Давайте подведём итог того, о чём договорились.'), ('Our main action item is the impact assessment. John, you own this.', 'Наш главный пункт — оценка влияния. Джон, вы отвечаете.'), ('Please send the minutes to everyone by tomorrow.', 'Пожалуйста, отправьте протокол всем до завтра.'), ('The deadline for the proposal is next Friday, July 3rd.', 'Дедлайн предложения — следующая пятница, 3 июля.'), ("Let's schedule a follow-up for next Tuesday to review.", 'Давайте назначим follow-up на следующий вторник.'), ('Does everyone agree on these next steps?', 'Все согласны с этими шагами?'), ('If there are no questions, we can wrap up here.', 'Если вопросов нет, можем заканчивать.'), ('Thank you all for your time today.', 'Спасибо всем за время.'), ("I'll share the meeting notes in an hour.", 'Я отправлю заметки через час.'), ("Let's confirm the next meeting: Tuesday, July 7th, 10 AM.", 'Подтвердим следующую встречу: вторник, 7 июля, 10 утра.')], words=[('summarize', 'резюмировать'), ('minutes', 'протокол'), ('schedule', 'назначить'), ('confirm', 'подтвердить'), ('wrap up', 'завершать'), ('action items', 'задачи')], checks=['Я могу подвести итог встречи с 3 пунктами', 'Я могу назначить ответственного и дедлайн', 'Я могу вежливо завершить встречу и договориться о следующей'], reading_title='Closing Vendor Meetings Effectively')
gen_day(6, title='Small Talk with Vendor', focus='Делать small talk с SAP-подрядчиком перед деловой частью', date='Пн 29 июн 2026', week_label='Week 2 — Заказчик → Подрядчик', review="Повторение D05: Закрой встречу: 'Let me summarize what we've agreed...' — 3 пункта.", phrases=[('How was your weekend? Did you do anything nice?', 'Как прошли выходные? Делали что-то приятное?'), ('How was your trip to Moscow last week?', 'Как поездка в Москву на прошлой неделе?'), ("The weather is really hot today, isn't it?", 'Погода сегодня очень жаркая, не так ли?'), ('Are you busy with other projects these days?', 'Вы заняты другими проектами сейчас?'), ("Okay, let's get down to business.", 'Хорошо, давайте перейдём к делу.'), ('I hope you had a good holiday.', 'Надеюсь, у вас был хороший отпуск.'), ('Did you manage to take some time off this summer?', 'Удалось отдохнуть этим летом?'), ("That's interesting. How long have you been working in SAP consulting?", 'Это интересно. Как давно вы в SAP-консалтинге?'), ('By the way, I saw your company won an award. Congratulations!', 'Кстати, видел, что ваша компания получила награду. Поздравляю!'), ("Let's start with the agenda. First topic is the Mercury integration.", 'Давайте начнём с повестки. Первая тема — интеграция с Меркурием.')], words=[('weekend', 'выходные'), ('holiday', 'отпуск'), ('congratulations', 'поздравления'), ('rapport', 'взаимопонимание'), ('award', 'награда'), ('briefly', 'кратко')], checks=['Я могу начать встречу с небольшого small talk', 'Я могу задать 2-3 непринуждённых вопроса перед делом', 'Я могу естественно перейти к повестке'], reading_title='The Art of Small Talk with Vendors')
